const points = $input.all().map(i => i.json);

const productos = {};
for (const p of points) {
  const payload = p.payload || {};
  const pid = payload.product_id;
  if (pid === undefined || pid === null) continue;
  if (!productos[pid]) {
    productos[pid] = {
      product_id: pid,
      title: payload.title ?? null,
      product_type: payload.product_type ?? null,
      descripcion: payload.descripcion ?? null,
      main_image_url: payload.main_image_url ?? null,
      top_score: p.score ?? 0,
      variantesPorId: {}
    };
  }
  const prod = productos[pid];
  prod.top_score = Math.max(prod.top_score, p.score ?? 0);
  if (!prod.main_image_url && payload.main_image_url) prod.main_image_url = payload.main_image_url;

  const vid = payload.variant_id;
  const key = (vid ?? `sin-variant-${Object.keys(prod.variantesPorId).length}`);
  if (!prod.variantesPorId[key]) {
    prod.variantesPorId[key] = {
      variant_id: vid ?? null,
      sku: payload.sku ?? null,
      color: payload.color ?? null,
      price: payload.price ?? null,
      inventory: payload.inventory ?? null,
      variant_image_url: payload.variant_image_url ?? null
    };
  }
}

// Maximo 3 productos distintos por mensaje (ordenados por score de busqueda), pero
// SIEMPRE todas las variantes de cada producto -- nunca se recorta la lista de variantes.
const lista = Object.values(productos)
  .sort((a, b) => b.top_score - a.top_score)
  .slice(0, 3)
  .map((prod) => {
    const variantes = Object.values(prod.variantesPorId);
    const precios = variantes.map((v) => v.price).filter((p) => p !== null && p !== undefined);
    const precio_min = precios.length ? Math.min(...precios) : null;
    const precio_max = precios.length ? Math.max(...precios) : null;

    const urls = new Set();
    if (prod.main_image_url) urls.add(prod.main_image_url);
    for (const v of variantes) {
      if (v.variant_image_url) urls.add(v.variant_image_url);
    }

    return {
      product_id: prod.product_id,
      title: prod.title,
      product_type: prod.product_type,
      descripcion: prod.descripcion,
      precio_min,
      precio_max,
      variantes,
      image_urls: Array.from(urls),
      main_image_url: prod.main_image_url
    };
  });

return lista.map((p) => ({ json: p }));

const items = $input.all();

return items.map((entry) => {
  const p = entry.json;

  const precio = (p.precio_min !== null && p.precio_max !== null)
    ? (p.precio_min === p.precio_max ? `$${p.precio_min}` : `$${p.precio_min} - $${p.precio_max}`)
    : 'Precio no disponible';

  const categoria = p.product_type || 'Sin categoria';
  const descripcionCorta = p.descripcion
    ? (p.descripcion.length > 160 ? `${p.descripcion.slice(0, 160)}...` : p.descripcion)
    : '';

  const lineasVariantes = (p.variantes || []).map((v) => {
    const color = v.color || 'Sin color';
    const sku = v.sku ? ` (SKU ${v.sku})` : '';
    const stock = (v.inventory !== null && v.inventory !== undefined) ? `${v.inventory} en stock` : 'stock no disponible';
    const precioVariante = (v.price !== null && v.price !== undefined) ? `$${v.price}` : 'precio no disponible';
    return `- ${color}${sku}: ${precioVariante}, ${stock}`;
  }).join('\n');

  const texto = [
    `*${p.title || 'Producto'}*`,
    `Categoria: ${categoria}`,
    `Precio: ${precio}`,
    descripcionCorta,
    '',
    'Variantes disponibles:',
    lineasVariantes
  ].filter(Boolean).join('\n');

  return { json: { ...p, text_body: texto } };
});

const items = $input.all();
const salida = [];

for (const entry of items) {
  const p = entry.json;
  const urls = p.image_urls || [];
  urls.forEach((url, idx) => {
    salida.push({
      json: {
        product_id: p.product_id,
        title: p.title,
        image_url: url,
        caption: `${p.title || 'Producto'}${urls.length > 1 ? ` (imagen ${idx + 1}/${urls.length})` : ''}`
      }
    });
  });
}

return salida;
